sp_widget.client_script:
api.controller = function($timeout) {

  var c = this;


  /* ============================================================
     INITIAL STATE
  ============================================================ */

  c.searchText = '';

  c.selectedInterview = null;

  c.saving = false;

  c.formError = '';

  c.formSuccess = '';


  c.form = {
    technical_score: null,
    communication_score: null,
    problem_solving_score: null,
    overall_score: null,
    strengths: '',
    improvement_areas: '',
    recommendation: ''
  };


  /* ============================================================
     SEARCH
  ============================================================ */

  c.filteredInterviews = function() {

    if (!c.data || !c.data.interviews) {
      return [];
    }


    var search =
      String(c.searchText || '')
        .toLowerCase()
        .trim();


    if (!search) {
      return c.data.interviews;
    }


    return c.data.interviews.filter(
      function(interview) {

        var values = [
          interview.studentName,
          interview.studentId,
          interview.interviewId,
          interview.interviewType,
          interview.interviewDate
        ];


        for (
          var i = 0;
          i < values.length;
          i++
        ) {

          if (
            String(values[i] || '')
              .toLowerCase()
              .indexOf(search) !== -1
          ) {

            return true;
          }
        }


        return false;
      }
    );
  };


  c.clearSearch = function() {

    c.searchText = '';

  };


  /* ============================================================
     OPEN INTERVIEW
  ============================================================ */

  c.openInterview = function(interview) {

    if (!interview) {
      return;
    }


    c.selectedInterview = interview;


    c.formError = '';

    c.formSuccess = '';


    c.form = {

      technical_score:
        interview.feedback &&
        interview.feedback.technical_score !== null
          ? interview.feedback.technical_score
          : null,

      communication_score:
        interview.feedback &&
        interview.feedback.communication_score !== null
          ? interview.feedback.communication_score
          : null,

      problem_solving_score:
        interview.feedback &&
        interview.feedback.problem_solving_score !== null
          ? interview.feedback.problem_solving_score
          : null,

      overall_score:
        interview.feedback &&
        interview.feedback.overall_score !== null
          ? interview.feedback.overall_score
          : null,

      strengths:
        interview.feedback &&
        interview.feedback.strengths
          ? interview.feedback.strengths
          : '',

      improvement_areas:
        interview.feedback &&
        interview.feedback.improvement_areas
          ? interview.feedback.improvement_areas
          : '',

      recommendation:
        interview.feedback &&
        interview.feedback.recommendation
          ? interview.feedback.recommendation
          : ''
    };


    $timeout(
      function() {

        var form =
          document.querySelector(
            '.c360-feedback-form-panel'
          );


        if (form) {

          form.scrollIntoView({
            behavior: 'smooth',
            block: 'start'
          });

        }

      },
      100
    );

  };


  /* ============================================================
     CLOSE INTERVIEW
  ============================================================ */

  c.closeInterview = function() {

    c.selectedInterview = null;

    c.formError = '';

    c.formSuccess = '';

  };


  /* ============================================================
     SCORE VALIDATION
  ============================================================ */

  function validateScore(
    value,
    label
  ) {

    if (
      value === null ||
      value === undefined ||
      value === ''
    ) {

      return {
        valid: false,
        message:
          label +
          ' is required.'
      };
    }


    var number =
      Number(value);


    if (
      isNaN(number) ||
      number < 0 ||
      number > 100
    ) {

      return {
        valid: false,
        message:
          label +
          ' must be between 0 and 100.'
      };
    }


    return {
      valid: true
    };
  }


  /* ============================================================
     SAVE FEEDBACK
  ============================================================ */

  c.saveFeedback = function() {

    if (
      !c.selectedInterview ||
      !c.selectedInterview.sys_id
    ) {

      return;
    }


    c.formError = '';

    c.formSuccess = '';


    /* SCORE VALIDATION */

    var technical =
      validateScore(
        c.form.technical_score,
        'Technical Score'
      );


    if (!technical.valid) {

      c.formError =
        technical.message;

      return;
    }


    var communication =
      validateScore(
        c.form.communication_score,
        'Communication Score'
      );


    if (!communication.valid) {

      c.formError =
        communication.message;

      return;
    }


    var problemSolving =
      validateScore(
        c.form.problem_solving_score,
        'Problem Solving Score'
      );


    if (!problemSolving.valid) {

      c.formError =
        problemSolving.message;

      return;
    }


    var overall =
      validateScore(
        c.form.overall_score,
        'Overall Score'
      );


    if (!overall.valid) {

      c.formError =
        overall.message;

      return;
    }


    /* TEXT VALIDATION */

    if (
      !String(
        c.form.strengths || ''
      ).trim()
    ) {

      c.formError =
        'Please enter the student strengths.';

      return;
    }


    if (
      !String(
        c.form.improvement_areas || ''
      ).trim()
    ) {

      c.formError =
        'Please enter the improvement areas.';

      return;
    }


    if (
      !String(
        c.form.recommendation || ''
      ).trim()
    ) {

      c.formError =
        'Please enter a recommendation.';

      return;
    }


    c.saving = true;


    c.server.get({

      action: 'save_feedback',

      interview_sys_id:
        c.selectedInterview.sys_id,

      technical_score:
        c.form.technical_score,

      communication_score:
        c.form.communication_score,

      problem_solving_score:
        c.form.problem_solving_score,

      overall_score:
        c.form.overall_score,

      strengths:
        c.form.strengths,

      improvement_areas:
        c.form.improvement_areas,

      recommendation:
        c.form.recommendation

    }).then(

      function(response) {

        c.saving = false;


        var result =
          response &&
          response.data
            ? response.data
            : null;


        if (
          !result ||
          !result.success
        ) {

          c.formError =
            result &&
            result.message
              ? result.message
              : 'Unable to save feedback.';

          return;
        }


        c.formSuccess =
          result.message ||
          'Feedback saved successfully.';


        /*
         * Update the selected interview locally
         * so the card immediately changes from
         * Pending to Feedback Given.
         */

        c.selectedInterview.hasFeedback =
          true;


        c.selectedInterview.feedback = {

          technical_score:
            Number(
              c.form.technical_score
            ),

          communication_score:
            Number(
              c.form.communication_score
            ),

          problem_solving_score:
            Number(
              c.form.problem_solving_score
            ),

          overall_score:
            Number(
              c.form.overall_score
            ),

          strengths:
            c.form.strengths,

          improvement_areas:
            c.form.improvement_areas,

          recommendation:
            c.form.recommendation

        };


        if (c.data) {

          c.data.feedbackCount =
            result.feedbackCount !== undefined
              ? result.feedbackCount
              : c.data.feedbackCount;


          c.data.pendingCount =
            result.pendingCount !== undefined
              ? result.pendingCount
              : c.data.pendingCount;

        }


        /*
         * Refresh the server data after a short delay.
         * This ensures the new record is reflected
         * everywhere on the page.
         */

        $timeout(
          function() {

            c.server.update();

          },
          700
        );

      },

      function() {

        c.saving = false;

        c.formError =
          'Unable to communicate with the server.';

      }
    );

  };


  /* ============================================================
     REFRESH
  ============================================================ */

  c.refresh = function() {

    c.server.update();

  };


  /* ============================================================
     ESC KEY
  ============================================================ */

  c.onKeyDown = function(event) {

    if (
      event &&
      event.keyCode === 27 &&
      c.selectedInterview
    ) {

      c.closeInterview();

    }

  };

};

sp_widget.css:
/* =========================================================
   CAMPUS360 TRAINER
   FEEDBACK & PERFORMANCE

   FULL SCREEN
   TRAINER DASHBOARD STYLE SIDEBAR
   TRAINER DASHBOARD STYLE TOPBAR
   FULL 100% PC VIEW
   DARK PURPLE SIDEBAR
   ========================================================= */


/* =========================================================
   RESET
   ========================================================= */

html,
body {

  width:100% !important;
  height:100% !important;

  margin:0 !important;
  padding:0 !important;

  min-width:100% !important;
  min-height:100% !important;

}


body {

  overflow-x:hidden !important;

  background:#f3f6fb !important;

}


.c360-feedback-app,
.c360-feedback-app *,
.c360-feedback-app *::before,
.c360-feedback-app *::after {

  box-sizing:border-box;

}


/* =========================================================
   SERVICENOW WRAPPER RESET
   ========================================================= */

.container:has(.c360-feedback-app),
.container-fluid:has(.c360-feedback-app),
.row:has(.c360-feedback-app),
[class*="col-"]:has(.c360-feedback-app),
.well:has(.c360-feedback-app),
.panel:has(.c360-feedback-app) {

  width:100% !important;

  max-width:none !important;

  min-width:0 !important;

  margin:0 !important;

  padding:0 !important;

  border:0 !important;

  background:transparent !important;

  box-shadow:none !important;

}


.panel:has(.c360-feedback-app)
.panel-body {

  width:100% !important;

  max-width:none !important;

  margin:0 !important;

  padding:0 !important;

}


/* =========================================================
   ROOT APPLICATION
   ========================================================= */

.c360-feedback-app {

  position:fixed !important;

  top:0 !important;
  left:0 !important;
  right:0 !important;
  bottom:0 !important;

  width:100vw !important;
  height:100vh !important;

  min-width:100vw !important;
  min-height:100vh !important;

  max-width:100vw !important;
  max-height:100vh !important;

  margin:0 !important;
  padding:0 !important;

  z-index:2147483647 !important;

  display:flex !important;

  flex-direction:row !important;

  overflow:hidden !important;

  isolation:isolate;

  background:

    radial-gradient(
      circle at 7% 8%,
      rgba(239,232,255,.60),
      transparent 24%
    ),

    radial-gradient(
      circle at 97% 7%,
      rgba(228,244,255,.58),
      transparent 25%
    ),

    linear-gradient(
      135deg,
      #f7f9fc 0%,
      #f3f7fb 55%,
      #faf7ff 100%
    );

  color:#24384e;

  font-family:
    "Segoe UI",
    "Inter",
    Arial,
    Helvetica,
    sans-serif;

  -webkit-font-smoothing:antialiased;

}


/* =========================================================
   SIDEBAR
   DARK PURPLE - SAME STYLE AS STUDENT PAGES
   ========================================================= */

.c360-feedback-sidebar {

  position:relative !important;

  top:0 !important;
  left:0 !important;

  width:280px !important;

  min-width:280px !important;
  max-width:280px !important;

  height:100vh !important;

  min-height:100vh !important;
  max-height:100vh !important;

  flex:0 0 280px !important;

  display:flex;

  flex-direction:column;

  overflow:hidden;

  background:
    linear-gradient(
      180deg,
      #130d2f 0%,
      #160d38 48%,
      #100a29 100%
    ) !important;

  border-right:1px solid #2d2157 !important;

  box-shadow:
    5px
    0
    18px
    rgba(10,7,30,.18);

  z-index:100;

  transition:
    width .25s ease,
    min-width .25s ease,
    max-width .25s ease,
    flex-basis .25s ease;

}


/* =========================================================
   COLLAPSED SIDEBAR
   ========================================================= */

.sidebar-collapsed
.c360-feedback-sidebar {

  width:0 !important;

  min-width:0 !important;

  max-width:0 !important;

  flex-basis:0 !important;

  border-right:0 !important;

}


/* =========================================================
   SIDEBAR BRAND
   ========================================================= */

.c360-feedback-brand {

  height:98px;

  min-height:98px;

  padding:0 17px;

  display:flex;

  align-items:center;

  gap:13px;

  flex-shrink:0;

  background:
    linear-gradient(
      135deg,
      #170e38,
      #1c1045
    ) !important;

  border-bottom:1px solid #2d2157 !important;

}


.c360-feedback-brand-mark {

  width:50px;

  height:50px;

  min-width:50px;

  display:flex;

  align-items:center;

  justify-content:center;

  border-radius:14px;

  background:
    linear-gradient(
      135deg,
      #7c3aed,
      #8b3ff2
    ) !important;

  color:#ffffff;

  font-size:23px;

  box-shadow:
    0
    8px
    18px
    rgba(124,58,237,.28);

}


.c360-feedback-brand-text {

  min-width:0;

  display:flex;

  flex-direction:column;

}


.c360-feedback-brand-text strong {

  display:block;

  color:#ffffff !important;

  font-size:21px;

  line-height:1;

  font-weight:900;

  letter-spacing:-.3px;

}


.c360-feedback-brand-text span {

  display:block;

  margin-top:5px;

  color:#b9abd8 !important;

  font-size:10px;

  line-height:1;

  font-weight:900;

  letter-spacing:1.25px;

}


/* =========================================================
   TRAINER MINI PROFILE
   ========================================================= */

.c360-feedback-profile {

  margin:
    18px
    10px
    15px;

  min-height:74px;

  padding:11px;

  display:flex;

  align-items:center;

  gap:10px;

  flex-shrink:0;

  background:
    linear-gradient(
      135deg,
      #211342,
      #29164f
    ) !important;

  border:1px solid #4b3475 !important;

  border-radius:13px;

  text-decoration:none !important;

  transition:
    background .18s ease,
    border-color .18s ease;

}


.c360-feedback-profile:hover {

  background:
    linear-gradient(
      135deg,
      #29174f,
      #321d5d
    ) !important;

  border-color:#60458e !important;

}


.c360-feedback-avatar {

  width:46px;

  height:46px;

  min-width:46px;

  display:flex;

  align-items:center;

  justify-content:center;

  border-radius:12px;

  background:
    linear-gradient(
      135deg,
      #7c3aed,
      #8b3ff2
    ) !important;

  color:#ffffff;

  font-size:13px;

  font-weight:900;

  box-shadow:
    0
    5px
    14px
    rgba(124,58,237,.20);

}


.c360-feedback-profile-info {

  min-width:0;

  flex:1;

}


.c360-feedback-profile-info strong {

  display:block;

  overflow:hidden;

  color:#ffffff !important;

  font-size:13px;

  line-height:1.2;

  font-weight:900;

  white-space:nowrap;

  text-overflow:ellipsis;

}


.c360-feedback-profile-info span {

  display:block;

  margin-top:4px;

  color:#b9abd8 !important;

  font-size:9px;

  font-weight:800;

}


.c360-feedback-profile > i {

  color:#a99bc7 !important;

  font-size:19px;

}


/* =========================================================
   SIDEBAR NAVIGATION
   ========================================================= */

.c360-feedback-nav {

  flex:1;

  min-height:0;

  padding:
    0
    6px
    20px;

  overflow-x:hidden;

  overflow-y:auto;

}


.c360-feedback-nav::-webkit-scrollbar {

  width:0 !important;
  height:0 !important;

}


.c360-feedback-nav {

  scrollbar-width:none !important;

  -ms-overflow-style:none !important;

}


.c360-feedback-nav-label {

  margin:
    18px
    7px
    8px;

  color:#9283b6 !important;

  font-size:10px;

  line-height:1;

  font-weight:900;

  letter-spacing:1.15px;

}


.c360-feedback-nav-item {

  position:relative;

  width:100%;

  min-height:48px;

  margin:
    2px
    0;

  padding:
    0
    11px;

  display:flex;

  align-items:center;

  gap:11px;

  border-radius:10px;

  background:transparent;

  color:#c4b8dc !important;

  text-decoration:none !important;

  font-size:13px;

  line-height:1.25;

  font-weight:850;

  transition:
    background .18s ease,
    color .18s ease,
    transform .18s ease;

}


.c360-feedback-nav-item:hover {

  background:
    rgba(124,58,237,.18) !important;

  color:#ffffff !important;

  transform:translateX(1px);

  text-decoration:none !important;

}


.c360-feedback-nav-item.active {

  color:#ffffff !important;

  background:
    linear-gradient(
      90deg,
      #7c3aed 0%,
      #8b3ff2 100%
    ) !important;

  border-left:
    4px
    solid
    #a78bfa !important;

  padding-left:7px;

  box-shadow:
    inset
    0
    0
    0
    1px
    rgba(196,181,253,.12),

    0
    7px
    18px
    rgba(124,58,237,.18);

}


.c360-feedback-nav-icon {

  width:28px;

  min-width:28px;

  height:28px;

  display:flex;

  align-items:center;

  justify-content:center;

  color:#a99ac8 !important;

  font-size:18px;

}


.c360-feedback-nav-item:hover
.c360-feedback-nav-icon {

  color:#ffffff !important;

}


.c360-feedback-nav-item.active
.c360-feedback-nav-icon {

  color:#ffffff !important;

}


.c360-feedback-nav-count {

  min-width:23px;

  height:23px;

  margin-left:auto;

  padding:
    0
    6px;

  display:flex;

  align-items:center;

  justify-content:center;

  border-radius:20px;

  background:#3a2764 !important;

  color:#d9ceef !important;

  font-size:9px;

  line-height:1;

  font-weight:900;

}


.c360-feedback-nav-item.active
.c360-feedback-nav-count {

  background:rgba(255,255,255,.18) !important;

  color:#ffffff !important;

}


.c360-feedback-nav-count.warning {

  background:#5a3511 !important;

  color:#ffd08a !important;

}


/* =========================================================
   SIDEBAR OVERLAY
   ========================================================= */

.c360-feedback-sidebar-overlay {

  display:none;

}


/* =========================================================
   MAIN
   ========================================================= */

.c360-feedback-main {

  width:
    calc(100vw - 280px) !important;

  max-width:
    calc(100vw - 280px) !important;

  min-width:0 !important;

  height:100vh !important;

  min-height:100vh !important;

  max-height:100vh !important;

  flex:1 1 auto;

  margin:0 !important;

  padding:0 !important;

  overflow-x:hidden !important;

  overflow-y:auto !important;

  background:#f3f6fb;

  transition:
    width .25s ease,
    max-width .25s ease;

}


.sidebar-collapsed
.c360-feedback-main {

  width:100% !important;

  max-width:100% !important;

}


/* =========================================================
   TOP NAVBAR
   ========================================================= */

.c360-feedback-topbar {

  position:sticky;

  top:0;

  z-index:500;

  width:100%;

  height:72px;

  min-height:72px;

  padding:
    0
    19px
    0
    22px;

  display:flex;

  align-items:center;

  justify-content:space-between;

  gap:18px;

  background:
    linear-gradient(
      90deg,
      #ffffff,
      #fbfdff
    );

  border-bottom:1px solid #dce4ec;

  box-shadow:
    0
    2px
    10px
    rgba(23,43,67,.035);

}


/* =========================================================
   TOPBAR LEFT
   ========================================================= */

.c360-feedback-topbar-left {

  min-width:0;

  display:flex;

  align-items:center;

  gap:12px;

}


.c360-feedback-hamburger {

  width:44px;

  height:44px;

  min-width:44px;

  display:flex;

  align-items:center;

  justify-content:center;

  border:
    1px
    solid
    #d6e0e8;

  border-radius:10px;

  background:#ffffff;

  color:#536a81;

  font-size:18px;

  cursor:pointer;

  transition:
    background .18s ease,
    color .18s ease,
    border-color .18s ease;

}


.c360-feedback-hamburger:hover {

  color:#6843df;

  background:#f5f1ff;

  border-color:#cec1f4;

}


.c360-feedback-page-heading {

  min-width:0;

  display:flex;

  flex-direction:column;

}


.c360-feedback-top-eyebrow {

  display:block;

  color:#7244e8;

  font-size:9px;

  line-height:1;

  font-weight:950;

  letter-spacing:1.7px;

}


.c360-feedback-top-title {

  display:block;

  margin-top:4px;

  color:#1a304a;

  font-size:16px;

  line-height:1.1;

  font-weight:900;

}


/* =========================================================
   TOPBAR RIGHT
   ========================================================= */

.c360-feedback-top-actions {

  display:flex;

  align-items:center;

  gap:9px;

  flex-shrink:0;

}


.c360-feedback-top-icon {

  position:relative;

  width:42px;

  height:42px;

  min-width:42px;

  display:flex;

  align-items:center;

  justify-content:center;

  border:
    1px
    solid
    #d7e0e8;

  border-radius:10px;

  background:#ffffff;

  color:#5b7187;

  font-size:16px;

  cursor:pointer;

}


.c360-feedback-top-icon:hover {

  color:#6843df;

  background:#f5f1ff;

  border-color:#cfc2f6;

}


/* =========================================================
   NOTIFICATION
   ========================================================= */

.c360-feedback-notification {

  overflow:visible;

}


.c360-feedback-notification
.fa-bell {

  color:#f3a100;

  font-size:17px;

}


.c360-feedback-notification-dot {

  position:absolute;

  top:7px;

  right:7px;

  width:8px;

  height:8px;

  border-radius:50%;

  background:#ef4444;

  border:
    2px
    solid
    #ffffff;

}


/* =========================================================
   TOP PROFILE
   ========================================================= */

.c360-feedback-top-profile {

  min-height:43px;

  padding-left:11px;

  display:flex;

  align-items:center;

  gap:8px;

  border-left:1px solid #e2e7ed;

  color:inherit;

  text-decoration:none !important;

}


.c360-feedback-top-avatar {

  width:42px;

  height:42px;

  min-width:42px;

  display:flex;

  align-items:center;

  justify-content:center;

  border-radius:10px;

  background:
    linear-gradient(
      135deg,
      #693ef2,
      #8053ff
    );

  color:#ffffff;

  font-size:10px;

  font-weight:900;

}


.c360-feedback-top-profile-text {

  min-width:75px;

  display:flex;

  flex-direction:column;

}


.c360-feedback-top-profile-text strong {

  display:block;

  color:#23384f;

  font-size:11px;

  line-height:1.1;

  font-weight:900;

}


.c360-feedback-top-profile-text span {

  display:block;

  margin-top:3px;

  color:#7c8a9c;

  font-size:8px;

  line-height:1;

  font-weight:750;

}


/* =========================================================
   CONTENT
   ========================================================= */

.c360-feedback-content {

  width:100% !important;

  max-width:none !important;

  min-width:0;

  margin:0 !important;

  padding:
    24px
    25px
    40px;

  background:

    radial-gradient(
      circle at 96% 12%,
      rgba(229,244,255,.30),
      transparent 24%
    ),

    radial-gradient(
      circle at 2% 58%,
      rgba(240,231,255,.32),
      transparent 24%
    ),

    #f3f6fb;

}


/* =========================================================
   PAGE HEADER
   ========================================================= */

.c360-feedback-page-header {

  width:100%;

  margin-bottom:19px;

  display:flex;

  align-items:center;

  justify-content:space-between;

  gap:24px;

}


.c360-feedback-eyebrow {

  display:block;

  color:#6942df;

  font-size:9px;

  font-weight:950;

  line-height:1;

  letter-spacing:1.7px;

}


.c360-feedback-page-header h1 {

  margin:
    7px
    0
    0;

  color:#182d48;

  font-size:34px;

  line-height:1.08;

  font-weight:950;

  letter-spacing:-.7px;

}


.c360-feedback-page-header p {

  margin:
    7px
    0
    0;

  color:#617289;

  font-size:13px;

  line-height:1.6;

  font-weight:600;

}


.c360-feedback-trainer-card {

  min-width:205px;

  padding:
    12px
    14px;

  display:flex;

  align-items:center;

  gap:10px;

  border:
    1px
    solid
    #ddd3f7;

  border-radius:12px;

  background:
    linear-gradient(
      135deg,
      #f8f4ff,
      #f2f8ff
    );

  box-shadow:
    0
    5px
    14px
    rgba(62,54,96,.045);

}


.c360-feedback-trainer-card-avatar {

  width:45px;

  height:45px;

  min-width:45px;

  display:flex;

  align-items:center;

  justify-content:center;

  border-radius:11px;

  background:
    linear-gradient(
      135deg,
      #6b3df4,
      #8054ff
    );

  color:#ffffff;

  font-size:11px;

  font-weight:900;

}


.c360-feedback-trainer-card > div:last-child > span {

  display:block;

  color:#8490a0;

  font-size:8px;

  line-height:1;

  font-weight:950;

  letter-spacing:1px;

}


.c360-feedback-trainer-card strong {

  display:block;

  margin-top:4px;

  color:#263b51;

  font-size:12px;

  line-height:1.15;

  font-weight:900;

}


.c360-feedback-trainer-card small {

  display:block;

  margin-top:3px;

  color:#7b899a;

  font-size:9px;

}


/* =========================================================
   SUMMARY
   ========================================================= */

.c360-feedback-summary-grid {

  width:100%;

  display:grid;

  grid-template-columns:
    repeat(
      4,
      minmax(0,1fr)
    );

  gap:14px;

  margin-bottom:18px;

}


.c360-feedback-summary-card {

  min-height:125px;

  padding:18px;

  display:flex;

  align-items:center;

  gap:13px;

  border:1px solid;

  border-radius:15px;

  box-shadow:
    0
    5px
    15px
    rgba(36,51,70,.04);

}


.c360-feedback-summary-card.lavender {

  background:
    linear-gradient(
      135deg,
      #f1eaff,
      #e6dcff
    );

  border-color:#d4c4fb;

}


.c360-feedback-summary-card.peach {

  background:
    linear-gradient(
      135deg,
      #fff2e7,
      #ffe4cf
    );

  border-color:#f1d0b2;

}


.c360-feedback-summary-card.blue {

  background:
    linear-gradient(
      135deg,
      #eaf7ff,
      #d9edff
    );

  border-color:#bfdcf2;

}


.c360-feedback-summary-card.green {

  background:
    linear-gradient(
      135deg,
      #e9f8f1,
      #d7efe3
    );

  border-color:#bee2cf;

}


.c360-feedback-summary-icon {

  width:51px;

  height:51px;

  min-width:51px;

  display:flex;

  align-items:center;

  justify-content:center;

  border-radius:14px;

  background:
    rgba(255,255,255,.86);

  font-size:21px;

}


.lavender
.c360-feedback-summary-icon {

  color:#6944dc;

}


.peach
.c360-feedback-summary-icon {

  color:#cd7841;

}


.blue
.c360-feedback-summary-icon {

  color:#277bb8;

}


.green
.c360-feedback-summary-icon {

  color:#23865c;

}


.c360-feedback-summary-card span {

  display:block;

  color:#68778a;

  font-size:8px;

  line-height:1.2;

  font-weight:950;

  letter-spacing:.9px;

}


.c360-feedback-summary-card strong {

  display:block;

  margin-top:6px;

  color:#142d48;

  font-size:29px;

  line-height:1;

  font-weight:950;

}


/* =========================================================
   FILTER PANEL
   ========================================================= */

.c360-feedback-filter-panel {

  width:100%;

  margin-bottom:18px;

  padding:
    21px;

  border:
    1px
    solid
    #dce4ec;

  border-radius:15px;

  background:#ffffff;

  box-shadow:
    0
    5px
    16px
    rgba(31,45,61,.04);

}


.c360-feedback-filter-title {

  display:flex;

  align-items:flex-start;

  justify-content:space-between;

  gap:15px;

}


.c360-feedback-filter-title > div > span {

  display:block;

  margin-bottom:5px;

  color:#6c48dc;

  font-size:8px;

  font-weight:950;

  letter-spacing:1.5px;

}


.c360-feedback-filter-title h2 {

  margin:0;

  color:#182d48;

  font-size:21px;

  line-height:1.15;

  font-weight:950;

}


.c360-feedback-filter-title p {

  margin:
    5px
    0
    0;

  color:#718095;

  font-size:10px;

}


.c360-feedback-clear-button {

  height:35px;

  padding:
    0
    11px;

  display:flex;

  align-items:center;

  gap:6px;

  border:
    1px
    solid
    #d8e0e8;

  border-radius:8px;

  background:#ffffff;

  color:#637488;

  font-size:9px;

  font-weight:850;

  cursor:pointer;

}


.c360-feedback-clear-button:hover {

  background:#f5f1ff;

  border-color:#cdc0f4;

  color:#6540d8;

}


.c360-feedback-search {

  position:relative;

  margin-top:15px;

}


.c360-feedback-search i {

  position:absolute;

  top:50%;

  left:14px;

  transform:translateY(-50%);

  color:#8796a6;

  font-size:14px;

}


.c360-feedback-search input {

  width:100%;

  height:46px;

  padding:
    0
    14px
    0
    40px;

  border:
    1px
    solid
    #d8e1ea;

  border-radius:9px;

  background:#fbfcfe;

  color:#23384f;

  font-size:11px;

  outline:none;

}


.c360-feedback-search input:focus {

  background:#ffffff;

  border-color:#9f89e9;

  box-shadow:
    0
    0
    0
    3px
    rgba(103,60,255,.07);

}


/* =========================================================
   INTERVIEW PANEL
   ========================================================= */

.c360-feedback-interview-panel {

  width:100%;

  margin-bottom:18px;

  padding:
    21px;

  border:
    1px
    solid
    #dce4ec;

  border-top:
    4px
    solid
    #9879e8;

  border-radius:15px;

  background:#ffffff;

  box-shadow:
    0
    6px
    18px
    rgba(31,45,61,.045);

}


.c360-feedback-panel-header {

  display:flex;

  align-items:center;

  justify-content:space-between;

  gap:15px;

  margin-bottom:16px;

  padding-bottom:14px;

  border-bottom:1px solid #e8edf2;

}


.c360-feedback-panel-header > div > span {

  display:block;

  margin-bottom:5px;

  color:#6945da;

  font-size:8px;

  font-weight:950;

  letter-spacing:1.5px;

}


.c360-feedback-panel-header h2 {

  margin:0;

  color:#182d48;

  font-size:21px;

  line-height:1.15;

  font-weight:950;

}


.c360-feedback-result-count {

  padding:
    7px
    10px;

  border-radius:18px;

  background:#eee8ff;

  border:1px solid #ddd0ff;

  color:#6544cc;

  font-size:8px;

  font-weight:900;

  white-space:nowrap;

}


/* =========================================================
   INTERVIEW LIST
   ========================================================= */

.c360-feedback-interview-list {

  display:flex;

  flex-direction:column;

  gap:11px;

}


/* =========================================================
   INTERVIEW CARD
   ========================================================= */

.c360-feedback-interview-card {

  position:relative;

  overflow:hidden;

  width:100%;

  min-height:100px;

  display:grid;

  grid-template-columns:
    minmax(190px,1.15fr)
    minmax(360px,2fr)
    minmax(130px,.7fr)
    auto;

  align-items:center;

  gap:16px;

  padding:
    15px
    16px;

  border:
    1px
    solid
    #dce4ec;

  border-radius:12px;

  background:#ffffff;

  transition:
    transform .18s ease,
    box-shadow .18s ease,
    border-color .18s ease;

}


.c360-feedback-interview-card:hover {

  transform:translateY(-2px);

  box-shadow:
    0
    8px
    19px
    rgba(37,48,70,.075);

  border-color:#cfc3f1;

}


.c360-feedback-interview-card::before {

  content:"";

  position:absolute;

  left:0;

  top:0;

  bottom:0;

  width:4px;

  background:#8a6de5;

}


.c360-feedback-interview-card:nth-child(4n + 1) {

  background:
    linear-gradient(
      110deg,
      #fcfaff,
      #ffffff
    );

}


.c360-feedback-interview-card:nth-child(4n + 2) {

  background:
    linear-gradient(
      110deg,
      #f9fcff,
      #ffffff
    );

}


.c360-feedback-interview-card:nth-child(4n + 3) {

  background:
    linear-gradient(
      110deg,
      #fffaf5,
      #ffffff
    );

}


.c360-feedback-interview-card:nth-child(4n + 4) {

  background:
    linear-gradient(
      110deg,
      #f7fcf9,
      #ffffff
    );

}


.c360-feedback-interview-card:nth-child(4n + 1)::before {

  background:#8769e5;

}


.c360-feedback-interview-card:nth-child(4n + 2)::before {

  background:#62a4d0;

}


.c360-feedback-interview-card:nth-child(4n + 3)::before {

  background:#df9b59;

}


.c360-feedback-interview-card:nth-child(4n + 4)::before {

  background:#57a180;

}


/* =========================================================
   STUDENT
   ========================================================= */

.c360-feedback-student-block {

  min-width:0;

  display:flex;

  align-items:center;

  gap:10px;

}


.c360-feedback-student-avatar {

  width:44px;

  height:44px;

  min-width:44px;

  display:flex;

  align-items:center;

  justify-content:center;

  border-radius:11px;

  background:#e9e0ff;

  color:#6543d3;

  font-size:11px;

  font-weight:950;

}


.c360-feedback-interview-card:nth-child(4n + 2)
.c360-feedback-student-avatar {

  background:#deefff;

  color:#307bad;

}


.c360-feedback-interview-card:nth-child(4n + 3)
.c360-feedback-student-avatar {

  background:#ffe9d7;

  color:#b56d2c;

}


.c360-feedback-interview-card:nth-child(4n + 4)
.c360-feedback-student-avatar {

  background:#dff1e7;

  color:#2e805e;

}


.c360-feedback-student-block > div:last-child {

  min-width:0;

}


.c360-feedback-student-block strong {

  display:block;

  overflow:hidden;

  color:#1d3148;

  font-size:12px;

  line-height:1.2;

  font-weight:950;

  white-space:nowrap;

  text-overflow:ellipsis;

}


.c360-feedback-student-block span {

  display:block;

  margin-top:3px;

  color:#768598;

  font-size:9px;

  font-weight:750;

}


/* =========================================================
   DETAILS
   ========================================================= */

.c360-feedback-interview-details {

  min-width:0;

  display:grid;

  grid-template-columns:
    repeat(4,minmax(0,1fr));

  gap:10px;

}


.c360-feedback-detail-item {

  min-width:0;

}


.c360-feedback-detail-item > span {

  display:block;

  color:#8794a5;

  font-size:7px;

  line-height:1;

  font-weight:950;

  letter-spacing:.8px;

}


.c360-feedback-detail-item > strong {

  display:block;

  overflow:hidden;

  margin-top:5px;

  color:#30465b;

  font-size:10px;

  line-height:1.25;

  font-weight:850;

  text-overflow:ellipsis;

  white-space:nowrap;

}


/* =========================================================
   STATUS
   ========================================================= */

.c360-feedback-interview-status {

  display:flex;

  flex-direction:column;

  align-items:flex-start;

  gap:6px;

}


.c360-feedback-status,
.c360-feedback-feedback-status {

  display:inline-flex;

  align-items:center;

  gap:5px;

  padding:
    6px
    9px;

  border-radius:18px;

  font-size:8px;

  line-height:1;

  font-weight:950;

  white-space:nowrap;

}


.c360-feedback-status.completed {

  background:#e3f6eb;

  border:1px solid #c5e7d4;

  color:#19744e;

}


.c360-feedback-feedback-status.given {

  background:#eee8ff;

  border:1px solid #ddd0ff;

  color:#6342ca;

}


.c360-feedback-feedback-status.pending {

  background:#fff0dc;

  border:1px solid #f0d3b0;

  color:#aa650d;

}


/* =========================================================
   ACTION
   ========================================================= */

.c360-feedback-action {

  display:flex;

  align-items:center;

  justify-content:flex-end;

}


.c360-feedback-button {

  min-height:38px;

  padding:
    0
    13px;

  display:inline-flex;

  align-items:center;

  justify-content:center;

  gap:6px;

  border:0;

  border-radius:8px;

  background:
    linear-gradient(
      135deg,
      #6740df,
      #7d5ceb
    );

  color:#ffffff;

  font-size:8px;

  line-height:1;

  font-weight:950;

  cursor:pointer;

  white-space:nowrap;

}


.c360-feedback-button:hover {

  background:
    linear-gradient(
      135deg,
      #5931cf,
      #704bdc
    );

  box-shadow:
    0
    6px
    14px
    rgba(103,64,223,.18);

}


/* =========================================================
   EMPTY
   ========================================================= */

.c360-feedback-empty {

  padding:
    48px
    20px;

  text-align:center;

  border:
    1px
    dashed
    #ded8eb;

  border-radius:10px;

  background:
    linear-gradient(
      135deg,
      #fcfbff,
      #f8fbff
    );

}


.c360-feedback-empty-icon {

  width:52px;

  height:52px;

  margin:
    0
    auto
    11px;

  display:flex;

  align-items:center;

  justify-content:center;

  border-radius:13px;

  background:#ece5ff;

  color:#6745ce;

  font-size:20px;

}


.c360-feedback-empty h3 {

  margin:0;

  color:#304359;

  font-size:16px;

  font-weight:900;

}


.c360-feedback-empty p {

  margin:
    6px
    0
    0;

  color:#8491a1;

  font-size:10px;

}


/* =========================================================
   FEEDBACK FORM
   ========================================================= */

.c360-feedback-form-panel {

  width:100%;

  margin-bottom:18px;

  padding:
    0
    21px
    21px;

  border:
    1px
    solid
    #dce4ec;

  border-top:
    4px
    solid
    #8d70e7;

  border-radius:15px;

  background:#ffffff;

  box-shadow:
    0
    7px
    22px
    rgba(50,47,84,.055);

  scroll-margin-top:20px;

}


.c360-feedback-form-header {

  margin:
    0
    -21px;

  padding:
    18px
    21px;

  display:flex;

  align-items:flex-start;

  justify-content:space-between;

  gap:15px;

  background:
    linear-gradient(
      90deg,
      #faf7ff,
      #ffffff
    );

  border-bottom:1px solid #e7e3f0;

}


.c360-feedback-form-header > div > span {

  display:block;

  color:#7456d5;

  font-size:8px;

  font-weight:950;

  letter-spacing:1.5px;

}


.c360-feedback-form-header h2 {

  margin:
    5px
    0
    0;

  color:#182d48;

  font-size:23px;

  line-height:1.1;

  font-weight:950;

}


.c360-feedback-form-header p {

  margin:
    5px
    0
    0;

  color:#68798c;

  font-size:10px;

}


.c360-feedback-close-button {

  width:35px;

  height:35px;

  min-width:35px;

  display:flex;

  align-items:center;

  justify-content:center;

  border:
    1px
    solid
    #d9d1ef;

  border-radius:9px;

  background:#f8f5ff;

  color:#6a5b8d;

  cursor:pointer;

}


.c360-feedback-close-button:hover {

  background:#eee8ff;

  color:#5a3bc1;

  border-color:#cabbe9;

}


/* =========================================================
   SELECTED INTERVIEW SUMMARY
   ========================================================= */

.c360-feedback-selected-summary {

  width:100%;

  margin:
    18px
    0;

  padding:9px;

  display:grid;

  grid-template-columns:
    repeat(
      6,
      minmax(0,1fr)
    );

  gap:9px;

  border:
    1px
    solid
    #e0e3ea;

  border-radius:10px;

  background:#fafbfd;

}


.c360-feedback-selected-summary > div {

  min-width:0;

  min-height:57px;

  padding:
    9px
    10px;

  border:
    1px
    solid
    #e3e7ed;

  border-radius:8px;

  background:#ffffff;

}


.c360-feedback-selected-summary > div:nth-child(1) {

  background:#f5efff;

  border-color:#ddd1fb;

}


.c360-feedback-selected-summary > div:nth-child(2) {

  background:#eef7ff;

  border-color:#d2e5f5;

}


.c360-feedback-selected-summary > div:nth-child(3) {

  background:#fff7ed;

  border-color:#eedbc4;

}


.c360-feedback-selected-summary > div:nth-child(4) {

  background:#eff9f4;

  border-color:#d0e7da;

}


.c360-feedback-selected-summary > div:nth-child(5) {

  background:#fff0f3;

  border-color:#efd5dd;

}


.c360-feedback-selected-summary > div:nth-child(6) {

  background:#fff9e7;

  border-color:#efdfb8;

}


.c360-feedback-selected-summary span {

  display:block;

  color:#8491a1;

  font-size:7px;

  line-height:1;

  font-weight:950;

  letter-spacing:.8px;

}


.c360-feedback-selected-summary strong {

  display:block;

  overflow:hidden;

  margin-top:5px;

  color:#31465b;

  font-size:10px;

  line-height:1.2;

  font-weight:850;

  text-overflow:ellipsis;

  white-space:nowrap;

}


/* =========================================================
   FORM SECTIONS
   ========================================================= */

.c360-feedback-form-section {

  padding:
    19px
    0;

  border-top:
    1px
    solid
    #e9edf2;

}


.c360-feedback-section-title {

  margin-bottom:15px;

}


.c360-feedback-section-title > span {

  display:block;

  color:#6b48d7;

  font-size:8px;

  font-weight:950;

  letter-spacing:1.4px;

}


.c360-feedback-section-title h3 {

  margin:
    5px
    0
    0;

  color:#1a2f48;

  font-size:18px;

  font-weight:950;

}


/* =========================================================
   SCORES
   ========================================================= */

.c360-feedback-score-grid {

  display:grid;

  grid-template-columns:
    repeat(
      4,
      minmax(0,1fr)
    );

  gap:12px;

}


.c360-feedback-score-field {

  padding:
    13px;

  border:
    1px
    solid
    #e1e5eb;

  border-radius:10px;

  background:#fbfcfe;

}


.c360-feedback-score-field:nth-child(1) {

  background:#f6f2ff;

  border-color:#ded5f6;

}


.c360-feedback-score-field:nth-child(2) {

  background:#f1f8ff;

  border-color:#d2e5f2;

}


.c360-feedback-score-field:nth-child(3) {

  background:#fff7ef;

  border-color:#eddac3;

}


.c360-feedback-score-field:nth-child(4) {

  background:#f1faf5;

  border-color:#cde6d8;

}


.c360-feedback-score-field label {

  display:block;

  margin-bottom:7px;

  color:#45596e;

  font-size:10px;

  font-weight:900;

}


.c360-feedback-score-field:nth-child(1) label {

  color:#7055c8;

}


.c360-feedback-score-field:nth-child(2) label {

  color:#4e81a8;

}


.c360-feedback-score-field:nth-child(3) label {

  color:#ad7139;

}


.c360-feedback-score-field:nth-child(4) label {

  color:#39805f;

}


.c360-feedback-score-input {

  display:flex;

  align-items:center;

  border:
    1px
    solid
    #d7dfe8;

  border-radius:8px;

  background:#ffffff;

  overflow:hidden;

}


.c360-feedback-score-input:focus-within {

  border-color:#9d88e8;

  box-shadow:
    0
    0
    0
    3px
    rgba(103,60,255,.07);

}


.c360-feedback-score-input input {

  width:100%;

  height:42px;

  padding:
    0
    9px;

  border:0;

  outline:0;

  background:transparent;

  color:#1d3249;

  font-size:13px;

  font-weight:850;

}


