  padding-right:9px;

  color:#8996a5;

  font-size:9px;

  font-weight:800;

  white-space:nowrap;

}


/* =========================================================
   TEXT FEEDBACK
   ========================================================= */

.c360-feedback-text-grid {

  display:grid;

  grid-template-columns:
    1fr
    1fr;

  gap:13px;

}


.c360-feedback-text-field {

  position:relative;

  padding:
    13px;

  border:
    1px
    solid
    #e0e5eb;

  border-radius:10px;

  background:#fbfcfe;

}


.c360-feedback-text-field:nth-child(1) {

  background:#f3faf7;

  border-color:#cfe5da;

}


.c360-feedback-text-field:nth-child(2) {

