  background:#f7f4ff;

  border-color:#ded5f3;

}


.c360-feedback-text-field label {

  display:block;

  margin-bottom:7px;

  color:#455a70;

  font-size:10px;

  font-weight:900;

}


.c360-feedback-text-field:nth-child(1) label {

