      90deg,
      #7c3aed 0%,
      #8b3ff2 100%
    ) !important;

  color:#ffffff !important;

}


/* =========================================================
   END
   ========================================================= */

sp_widget.script:
(function() {

  /* ============================================================
     CAMPUS360 TRAINER FEEDBACK
     ============================================================

     TABLES USED:

     Trainer Master:
     x_snc_campus360_trainer_master

     Mock Interview:
     x_snc_campus360_mock_interview

     Interview Feedback:
     x_snc_campus360_interview_feedback

     Student Master:
     x_snc_campus360_student_master

     ============================================================ */


  var TRAINER_TABLE =
    'x_snc_campus360_trainer_master';

  var INTERVIEW_TABLE =
    'x_snc_campus360_mock_interview';

  var FEEDBACK_TABLE =
    'x_snc_campus360_interview_feedback';

  var STUDENT_TABLE =
    'x_snc_campus360_student_master';


  /* ============================================================
     INITIAL DATA
  ============================================================ */

  data.loaded = false;

  data.error = '';

  data.trainer = null;

  data.interviews = [];

  data.completedCount = 0;

  data.feedbackCount = 0;

  data.pendingCount = 0;

  data.reviewedStudentCount = 0;


  /* ============================================================
     CURRENT TRAINER
  ============================================================ */

  var requestedTrainerId =
    String(
      $sp.getParameter('trainer') || ''
    ).trim();


  var trainerGR =
    new GlideRecord(
      TRAINER_TABLE
    );


  if (requestedTrainerId) {

    trainerGR.addQuery(
      'trainer_id',
      requestedTrainerId
    );

    trainerGR.setLimit(1);

    trainerGR.query();

  } else {

    trainerGR.addQuery(
      'status',
      'Active'
    );

    trainerGR.orderBy(
      'trainer_id'
    );

    trainerGR.setLimit(1);

    trainerGR.query();

  }


  /* ============================================================
     TRAINER NOT FOUND
  ============================================================ */

  if (!trainerGR.next()) {

    data.loaded = true;

    data.error =
      'No trainer record found in Trainer Master.';

    return;

  }


  var trainerSysId =
    trainerGR.getUniqueValue();


  var trainerId =
    trainerGR.getValue(
      'trainer_id'
    ) || '';


  var trainerName =
    trainerGR.getValue(
      'trainer_name'
    ) || '';


  data.trainer = {

    sys_id:
      trainerSysId,

    id:
      trainerId,

    name:
      trainerName,

    email:
      trainerGR.getValue(
        'email'
      ) || '',

    expertise:
      trainerGR.getValue(
        'expertise'
      ) || '',

    experience:
      trainerGR.getValue(
        'experience'
      ) || '0',

    rating:
      trainerGR.getValue(
        'rating'
      ) || '0',

    status:
      trainerGR.getValue(
        'status'
      ) || '',

    totalInterviews:
      parseInt(
        trainerGR.getValue(
          'total_interviews'
        ),
        10
      ) || 0,

    initials:
      getInitials(
        trainerName
      )

  };


  /* ============================================================
     SAVE FEEDBACK ACTION
  ============================================================ */

  if (
    input &&
    input.action == 'save_feedback'
  ) {

    saveFeedback(
      trainerSysId
    );

    data.loaded = true;

    return;

  }


  /* ============================================================
     LOAD COMPLETED INTERVIEWS
  ============================================================ */

  loadCompletedInterviews(
    trainerSysId
  );


  data.loaded = true;


  /* ============================================================
     LOAD COMPLETED INTERVIEWS
  ============================================================ */

  function loadCompletedInterviews(
    trainerSysId
  ) {

    var studentMap = {};

    var interviewGR =
      new GlideRecord(
        INTERVIEW_TABLE
      );


    if (
      !interviewGR.isValidField(
        'trainer'
      )
    ) {

      data.error =
        'Trainer field was not found in Mock Interview table.';

      return;

    }


    interviewGR.addQuery(
      'trainer',
      trainerSysId
    );


    if (
      interviewGR.isValidField(
        'interview_status'
      )
    ) {

      interviewGR.addQuery(
        'interview_status',
        'Completed'
      );

    }


    if (
      interviewGR.isValidField(
        'interview_date'
      )
    ) {

      interviewGR.orderByDesc(
        'interview_date'
      );

    }


    interviewGR.query();


    while (
      interviewGR.next()
    ) {

      var interviewSysId =
        interviewGR.getUniqueValue();


      var studentSysId =
        interviewGR.getValue(
          'student'
        ) || '';


      var studentInfo =
        getStudentInfo(
          studentSysId,
          interviewGR.getDisplayValue(
            'student'
          )
        );


      var feedback =
        getFeedbackForInterview(
          interviewSysId
        );


      var interviewId =
        interviewGR.getValue(
          'interview_id'
        ) ||
        interviewGR.getDisplayValue(
          'interview_id'
        ) ||
        interviewSysId;


      var interviewType =
        interviewGR.getDisplayValue(
          'interview_type'
        ) ||
        interviewGR.getValue(
          'interview_type'
        ) ||
        'Mock Interview';


      var interviewDate =
        formatDate(
          interviewGR.getValue(
            'interview_date'
          )
        );


      var startTime =
        interviewGR.getValue(
          'start_time'
        ) || '';


      var endTime =
        interviewGR.getValue(
          'end_time'
        ) || '';


      var attendanceStatus =
        interviewGR.getDisplayValue(
          'attendance_status'
        ) ||
        interviewGR.getValue(
          'attendance_status'
        ) ||
        '';


      var interviewObject = {

        sys_id:
          interviewSysId,

        studentName:
          studentInfo.name,

        studentId:
          studentInfo.id,

        studentInitials:
          getInitials(
            studentInfo.name
          ),

        interviewId:
          interviewId,

        interviewType:
          interviewType,

        interviewDate:
          interviewDate,

        startTime:
          startTime,

        endTime:
          endTime,

        attendanceStatus:
          attendanceStatus,

        hasFeedback:
          feedback !== null,

        feedback:
          feedback

      };


      data.interviews.push(
        interviewObject
      );


      data.completedCount++;


      if (
        feedback !== null
      ) {

        data.feedbackCount++;


        if (
          studentSysId &&
          !studentMap[
            studentSysId
          ]
        ) {

          studentMap[
            studentSysId
          ] = true;

        }

      } else {

        data.pendingCount++;

      }

    }


    data.reviewedStudentCount =
      countKeys(
        studentMap
      );

  }


  /* ============================================================
     STUDENT INFORMATION
  ============================================================ */

  function getStudentInfo(
    studentSysId,
    fallbackName
  ) {

    var result = {

      id: '',

      name:
        fallbackName ||
        'Student'

    };


    if (
      !studentSysId
    ) {

      return result;

    }


    var studentGR =
      new GlideRecord(
        STUDENT_TABLE
      );


    if (
      !studentGR.get(
        studentSysId
      )
    ) {

      return result;

    }


    if (
      studentGR.isValidField(
        'student_id'
      )
    ) {

      result.id =
        studentGR.getValue(
          'student_id'
        ) || '';

    }


    if (
      studentGR.isValidField(
        'student_name'
      )
    ) {

      result.name =
        studentGR.getValue(
          'student_name'
        ) ||
        studentGR.getDisplayValue() ||
        result.name;

    } else {

      result.name =
        studentGR.getDisplayValue() ||
        result.name;

    }


    return result;

  }


  /* ============================================================
     EXISTING FEEDBACK FOR INTERVIEW
  ============================================================ */

  function getFeedbackForInterview(
    interviewSysId
  ) {

    if (
      !interviewSysId
    ) {

      return null;

    }


    var feedbackGR =
      new GlideRecord(
        FEEDBACK_TABLE
      );


    if (
      !feedbackGR.isValidField(
        'interview'
      )
    ) {

      return null;

    }


    feedbackGR.addQuery(
      'interview',
      interviewSysId
    );


    feedbackGR.orderByDesc(
      'sys_created_on'
    );


    feedbackGR.setLimit(1);

    feedbackGR.query();


    if (
      !feedbackGR.next()
    ) {

      return null;

    }


    return {

      sys_id:
        feedbackGR.getUniqueValue(),

      feedback_id:
        getValue(
          feedbackGR,
          'feedback_id'
        ),

      technical_score:
        getNumber(
          feedbackGR,
          'technical_score'
        ),

      communication_score:
        getNumber(
          feedbackGR,
          'communication_score'
        ),

      problem_solving_score:
        getNumber(
          feedbackGR,
          'problem_solving_score'
        ),

      overall_score:
        getNumber(
          feedbackGR,
          'overall_score'
        ),

      strengths:
        getValue(
          feedbackGR,
          'strengths'
        ),

      improvement_areas:
        getValue(
          feedbackGR,
          'improvement_areas'
        ),

      recommendation:
        getValue(
          feedbackGR,
          'recommendation'
        ),

      feedback_date:
        feedbackGR.getDisplayValue(
          'feedback_date'
        )

    };

  }


  /* ============================================================
     SAVE FEEDBACK
  ============================================================ */

  function saveFeedback(
    trainerSysId
  ) {

    var result = {

      success: false,

      message: '',

      feedbackCount:
        0,

      pendingCount:
        0

    };


    /* ------------------------------------------------------------
       REQUIRED INTERVIEW
    ------------------------------------------------------------ */

    var interviewSysId =
      String(
        input.interview_sys_id || ''
      ).trim();


    if (
      !interviewSysId
    ) {

      result.message =
        'No mock interview was selected.';

      data.success =
        false;

      data.message =
        result.message;

      return;

    }


    /* ------------------------------------------------------------
       VERIFY INTERVIEW
       Trainer must own this interview.
    ------------------------------------------------------------ */

    var interviewGR =
      new GlideRecord(
        INTERVIEW_TABLE
      );


    if (
      !interviewGR.get(
        interviewSysId
      )
    ) {

      result.message =
        'The selected mock interview could not be found.';

      data.success =
        false;

      data.message =
        result.message;

      return;

    }


    if (
      interviewGR.getValue(
        'trainer'
      ) != trainerSysId
    ) {

      result.message =
        'You are not allowed to give feedback for this interview.';

      data.success =
        false;

      data.message =
        result.message;

      return;

    }


    var interviewStatus =
      interviewGR.getValue(
        'interview_status'
      ) || '';


    if (
      String(
        interviewStatus
      ).toLowerCase() !=
      'completed'
    ) {

      result.message =
        'Feedback can only be submitted for a completed mock interview.';

      data.success =
        false;

      data.message =
        result.message;

      return;

    }


    /* ------------------------------------------------------------
       STUDENT
    ------------------------------------------------------------ */

    var studentSysId =
      interviewGR.getValue(
        'student'
      ) || '';


    if (
      !studentSysId
    ) {

      result.message =
        'The selected interview does not have a student.';

      data.success =
        false;

      data.message =
        result.message;

      return;

    }


    /* ------------------------------------------------------------
       SCORE VALIDATION
    ------------------------------------------------------------ */

    var technical =
      validateScore(
        input.technical_score,
        'Technical Score'
      );


    if (!technical.valid) {

      data.success =
        false;

      data.message =
        technical.message;

      return;

    }


    var communication =
      validateScore(
        input.communication_score,
        'Communication Score'
      );


    if (!communication.valid) {

      data.success =
        false;

      data.message =
        communication.message;

      return;

    }


    var problemSolving =
      validateScore(
        input.problem_solving_score,
        'Problem Solving Score'
      );


    if (!problemSolving.valid) {

      data.success =
        false;

      data.message =
        problemSolving.message;

      return;

    }


    var overall =
      validateScore(
        input.overall_score,
        'Overall Score'
      );


    if (!overall.valid) {

      data.success =
        false;

      data.message =
        overall.message;

      return;

    }


    /* ------------------------------------------------------------
       TEXT VALIDATION
    ------------------------------------------------------------ */

    var strengths =
      String(
        input.strengths || ''
      ).trim();


    var improvementAreas =
      String(
        input.improvement_areas || ''
      ).trim();


    var recommendation =
      String(
        input.recommendation || ''
      ).trim();


    if (
      !strengths
    ) {

      data.success =
        false;

      data.message =
        'Strengths are required.';

      return;

    }


    if (
      !improvementAreas
    ) {

      data.success =
        false;

      data.message =
        'Improvement Areas are required.';

      return;

    }


    if (
      !recommendation
    ) {

      data.success =
        false;

      data.message =
        'Recommendation is required.';

      return;

    }


    /* ------------------------------------------------------------
       FIND EXISTING FEEDBACK
       ------------------------------------------------------------

       One feedback record is maintained for one interview.

       If feedback already exists, update it.

       Otherwise create a new record.
    */

    var feedbackGR =
      new GlideRecord(
        FEEDBACK_TABLE
      );


    feedbackGR.addQuery(
      'interview',
      interviewSysId
    );


    feedbackGR.setLimit(1);

    feedbackGR.query();


    var isNew =
      false;


    if (
      feedbackGR.next()
    ) {

      /* Existing feedback */

    } else {

      /* New feedback */

      feedbackGR =
        new GlideRecord(
          FEEDBACK_TABLE
        );

      feedbackGR.initialize();

      isNew = true;

    }


    /* ------------------------------------------------------------
       SET REFERENCES
    ------------------------------------------------------------ */

    if (
      feedbackGR.isValidField(
        'student'
      )
    ) {

      feedbackGR.setValue(
        'student',
        studentSysId
      );

    }


    if (
      feedbackGR.isValidField(
        'trainer'
      )
    ) {

      feedbackGR.setValue(
        'trainer',
        trainerSysId
      );

    }


    if (
      feedbackGR.isValidField(
        'interview'
      )
    ) {

      feedbackGR.setValue(
        'interview',
        interviewSysId
      );

    }


    /* ------------------------------------------------------------
       SET SCORES
    ------------------------------------------------------------ */

    feedbackGR.setValue(
      'technical_score',
      String(
        technical.value
      )
    );


    feedbackGR.setValue(
      'communication_score',
      String(
        communication.value
      )
    );


    feedbackGR.setValue(
      'problem_solving_score',
      String(
        problemSolving.value
      )
    );


    feedbackGR.setValue(
      'overall_score',
      String(
        overall.value
      )
    );


    /* ------------------------------------------------------------
       SET TEXT
    ------------------------------------------------------------ */

    feedbackGR.setValue(
      'strengths',
      strengths
    );


    feedbackGR.setValue(
      'improvement_areas',
      improvementAreas
    );


    feedbackGR.setValue(
      'recommendation',
      recommendation
    );


    /* ------------------------------------------------------------
       FEEDBACK DATE
    ------------------------------------------------------------ */

    if (
      feedbackGR.isValidField(
        'feedback_date'
      )
    ) {

      feedbackGR.setValue(
        'feedback_date',
        new GlideDateTime()
      );

    }


    /* ------------------------------------------------------------
       FEEDBACK ID
    ------------------------------------------------------------ */

    if (
      isNew &&
      feedbackGR.isValidField(
        'feedback_id'
      )
    ) {

      feedbackGR.setValue(
        'feedback_id',
        generateFeedbackId()
      );

    }


    /* ------------------------------------------------------------
       SAVE
    ------------------------------------------------------------ */

    var savedId;


    if (
      isNew
    ) {

      savedId =
        feedbackGR.insert();

    } else {

      savedId =
        feedbackGR.update();

    }


    if (
      !savedId
    ) {

      result.message =
        'The feedback record could not be saved.';

      data.success =
        false;

      data.message =
        result.message;

      return;

    }


    /* ------------------------------------------------------------
       RETURN UPDATED COUNTS
    ------------------------------------------------------------ */

    result.success =
      true;


    result.message =
      isNew
        ? 'Interview feedback saved successfully.'
        : 'Interview feedback updated successfully.';


    result.feedbackCount =
      countTrainerFeedback(
        trainerSysId
      );


    result.pendingCount =
      countPendingFeedback(
        trainerSysId
      );


    data.success =
      true;

    data.message =
      result.message;

    data.feedbackCount =
      result.feedbackCount;

    data.pendingCount =
      result.pendingCount;

  }


  /* ============================================================
     SCORE VALIDATION
  ============================================================ */

  function validateScore(
    rawValue,
    label
  ) {

    if (
      rawValue === null ||
      rawValue === undefined ||
      rawValue === ''
    ) {

      return {

        valid: false,

        message:
          label +
          ' is required.'

      };

    }


    var number =
      parseFloat(
        rawValue
      );


    if (
      isNaN(number) ||
      number < 0 ||
      number > 100
    ) {

      return {

        valid: false,

        message:
          label +
          ' must be between 0 and 100.'

      };

    }


    return {

      valid: true,

      value: number

    };

  }


  /* ============================================================
     COUNT TRAINER FEEDBACK
  ============================================================ */

  function countTrainerFeedback(
    trainerSysId
  ) {

    var gr =
      new GlideRecord(
        FEEDBACK_TABLE
      );


    gr.addQuery(
      'trainer',
      trainerSysId
    );


    gr.query();


    var count =
      0;


    while (
      gr.next()
    ) {

      count++;

    }


    return count;

  }


  /* ============================================================
     COUNT PENDING FEEDBACK
  ============================================================ */

  function countPendingFeedback(
    trainerSysId
  ) {

    var count =
      0;


    var interviewGR =
      new GlideRecord(
        INTERVIEW_TABLE
      );


    interviewGR.addQuery(
      'trainer',
      trainerSysId
    );


    interviewGR.addQuery(
      'interview_status',
      'Completed'
    );


    interviewGR.query();


    while (
      interviewGR.next()
    ) {

      var feedbackGR =
        new GlideRecord(
          FEEDBACK_TABLE
        );


      feedbackGR.addQuery(
        'interview',
        interviewGR.getUniqueValue()
      );


      feedbackGR.setLimit(1);

      feedbackGR.query();


      if (
        !feedbackGR.next()
      ) {

        count++;

      }

    }


    return count;

  }


  /* ============================================================
     FEEDBACK ID
  ============================================================ */

  function generateFeedbackId() {

    var base =
      'FDB' +
      String(
        new GlideDateTime()
          .getNumericValue()
      );


    /*
     * Feedback ID field has max length 20.
     */

    if (
      base.length > 20
    ) {

      base =
        base.substring(
          0,
          20
        );

    }


    var candidate =
      base;


    var suffix =
      1;


    while (
      feedbackIdExists(
        candidate
      )
    ) {

      var suffixText =
        String(
          suffix
        );


      candidate =
        base.substring(
          0,
          20 -
          suffixText.length
        ) +
        suffixText;


      suffix++;

    }


    return candidate;

  }


  /* ============================================================
     FEEDBACK ID EXISTS
  ============================================================ */

  function feedbackIdExists(
    feedbackId
  ) {

    var gr =
      new GlideRecord(
        FEEDBACK_TABLE
      );


    gr.addQuery(
      'feedback_id',
      feedbackId
    );


    gr.setLimit(1);

    gr.query();


    return gr.next();

  }


  /* ============================================================
     GENERIC VALUE
  ============================================================ */

  function getValue(
    gr,
    fieldName
  ) {

    if (
      !gr ||
      !fieldName ||
      !gr.isValidField(
        fieldName
      )
    ) {

      return '';

    }


    return (
      gr.getValue(
        fieldName
      ) || ''
    );

  }


  /* ============================================================
     GENERIC NUMBER
  ============================================================ */

  function getNumber(
    gr,
    fieldName
  ) {

    var raw =
      getValue(
        gr,
        fieldName
      );


    if (
      raw === ''
    ) {

      return null;

    }


    var number =
      parseFloat(
        raw
      );


    return isNaN(
      number
    )
      ? null
      : number;

  }


  /* ============================================================
     DATE FORMAT
  ============================================================ */

  function formatDate(
    value
  ) {

    if (
      !value
    ) {

      return '';

    }


    var text =
      String(
        value
      );


    if (
      text.length >= 10
    ) {

      return text.substring(
        0,
        10
      );

    }


    return text;

  }


  /* ============================================================
     INITIALS
  ============================================================ */

  function getInitials(
    name
  ) {

    if (
      !name
    ) {

      return 'TR';

    }


    var parts =
      String(
        name
      )
      .trim()
      .split(
        /\s+/
      );


    var result =
      '';


    if (
      parts.length > 0
    ) {

      result +=
        parts[0]
          .charAt(0);

    }


    if (
      parts.length > 1
    ) {

      result +=
        parts[
          parts.length - 1
        ].charAt(0);

    }


    return result
      .toUpperCase()
      .substring(
        0,
        2
      );

  }


  /* ============================================================
     COUNT OBJECT KEYS
  ============================================================ */

  function countKeys(
    object
  ) {

    var count =
      0;


    for (
      var key in object
    ) {

      if (
        object.hasOwnProperty(
          key
        )
      ) {

        count++;

      }

    }


    return count;

  }


})();

